import {calculate, CATEGORIES, validProject, migrateProject, consultantProblems, todayISO} from './finance.js?v=3';
import {initPlanner} from './planner-ui.js?v=3';

const $ = id => document.getElementById(id);
const money = v => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:2}).format(v);
const percent = v => new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(v);
const signed = v => (v > 0 ? '+ ' : '') + money(v);
const uid = () => crypto.randomUUID();
const KEYS = {draft:'marge-draft-v3',projects:'marge-projects-v3'};
let toastTimer, activeId=null, storageAvailable=true;
function readStorage(key,fallback){try{const raw=localStorage.getItem(key);return raw ? JSON.parse(raw) : fallback;}catch{return fallback;}}
function writeStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));storageAvailable=true;return true;}catch{storageAvailable=false;return false;}}
function expense(category,more={}){return {id:uid(),name:CATEGORIES[category],category,calculation:'amount',quantity:1,price:0,rate:0,frequency:'monthly',variable:false,serviceId:'',...more};}
function blankProject(){return {version:3,name:'Mon prochain projet',months:12,investment:0,startDate:todayISO(),consultants:[],defaultCostModel:null,revenues:[],expenses:[]};}
function exampleProject(){const p=blankProject();p.investment=8000;p.revenues=[
  {id:uid(),name:'Conseil',kind:'service',quantity:5,price:1200,frequency:'monthly'},
  {id:uid(),name:'Formation',kind:'service',quantity:2,price:1500,frequency:'monthly'},
  {id:uid(),name:'Suivi client',kind:'service',quantity:4,price:250,frequency:'monthly'}
];p.expenses=[
  expense('flights',{quantity:2,price:350,serviceId:p.revenues[1].id}),
  expense('lodging',{quantity:4,price:100,serviceId:p.revenues[1].id}),
  expense('taxes',{calculation:'percent',rate:2}),
  expense('contractors',{quantity:5,price:150,variable:true,serviceId:p.revenues[0].id}),
  expense('salaries',{price:2800}),expense('other',{name:'Abonnements et frais de fonctionnement',price:500})
];return p;}
const oldDraft=readStorage('marge-draft-v2',null)||readStorage('marge-draft-v1',null);
const draft=readStorage(KEYS.draft,null) || oldDraft;
const rawProjects=readStorage(KEYS.projects,null) ?? readStorage('marge-projects-v2',null) ?? readStorage('marge-projects-v1',[]);
let projects=(Array.isArray(rawProjects)?rawProjects:[]).filter(item=>item&&typeof item.id==='string').map(item=>({...item,data:migrateProject(item.data)})).filter(item=>item.data);
let project=migrateProject(draft?.project) || exampleProject();
activeId=projects.some(item=>item.id===draft?.activeId)?draft.activeId:null;
const migrated=!!draft?.project && draft.project.version!==3 && !!migrateProject(draft.project);
if(!writeStorage(KEYS.projects,projects))storageAvailable=false;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function saveDraft(){const ok=writeStorage(KEYS.draft,{project,activeId});$('draftState').replaceChildren();const dot=document.createElement('span');$('draftState').append(dot,document.createTextNode(ok?'Brouillon enregistré':'Stockage indisponible'));}
function switchTab(name,focus=false){for(const key of ['consultants','revenues','expenses']){const selected=key===name;$(key+'Panel').hidden=!selected;$(key+'Tab').classList.toggle('selected',selected);$(key+'Tab').setAttribute('aria-selected',String(selected));$(key+'Tab').tabIndex=selected?0:-1;}if(focus)$(name+'Tab').focus();}
function fieldValue(card,field){return card.querySelector(`[data-field="${field}"]`);}
function setValues(card,line){for(const [key,value] of Object.entries(line)){const input=fieldValue(card,key);if(input){if(input.type==='checkbox')input.checked=value;else input.value=value;}}}
function categoryOptions(select){for(const [key,name]of Object.entries(CATEGORIES)){const option=document.createElement('option');option.value=key;option.textContent=name;select.append(option);}}
function serviceOptions(select,selected=''){select.replaceChildren();const common=document.createElement('option');common.value='';common.textContent='Projet entier / coût commun';select.append(common);for(const r of [...project.revenues,...project.consultants]){const opt=document.createElement('option');opt.value=r.id;opt.textContent=r.name||'Revenu sans nom';select.append(opt);}select.value=[...project.revenues,...project.consultants].some(r=>r.id===selected)?selected:'';}
function cardBase(line,index,type){const card=document.createElement('article');card.className='editor-card';card.dataset.id=line.id;card.dataset.type=type;card.setAttribute('aria-label',line.name);return card;}
function revenueCard(line,index){const card=cardBase(line,index,'revenue');card.innerHTML=`
  <div class="line-heading"><span class="line-index"></span><label class="line-name"><span class="sr-only">Nom du service ou produit</span><input data-field="name" type="text" maxlength="100" placeholder="Nom du service ou produit"></label><label class="kind-select"><span class="sr-only">Type de revenu</span><select data-field="kind"><option value="service">Service</option><option value="product">Produit</option></select></label><button type="button" class="remove-line" aria-label="Supprimer ce revenu">×</button></div>
  <div class="line-fields"><label>Quantité<div class="input-wrap"><input data-field="quantity" type="number" min="0" max="10000000" step="0.01" required inputmode="decimal"></div></label><label>Prix unitaire<div class="input-wrap"><input data-field="price" type="number" min="0" max="100000000" step="0.01" required inputmode="decimal"><span>€</span></div></label><label>Fréquence<select data-field="frequency"><option value="monthly">Par mois</option><option value="once">Pour le projet</option></select></label></div>
  <div class="line-footer"><span>Total sur <span class="months-label"></span> mois</span><strong class="line-total">—</strong></div>`;
  card.querySelector('.line-index').textContent=String(index+1).padStart(2,'0');setValues(card,line);
  card.querySelector('.remove-line').addEventListener('click',()=>removeLine('revenue',line.id));return card;
}
function expenseCard(line,index){const card=cardBase(line,index,'expense');card.innerHTML=`
  <div class="line-heading"><span class="category-dot"></span><label class="line-name"><span class="sr-only">Nom de la dépense</span><input data-field="name" type="text" maxlength="100" placeholder="Nom de la dépense"></label><button type="button" class="remove-line" aria-label="Supprimer cette dépense">×</button></div>
  <div class="line-fields amount-fields"><label>Quantité<div class="input-wrap"><input data-field="quantity" type="number" min="0" max="10000000" step="0.01" required inputmode="decimal"></div></label><label>Coût unitaire<div class="input-wrap"><input data-field="price" type="number" min="0" max="100000000" step="0.01" required inputmode="decimal"><span>€</span></div></label><label>Fréquence<select data-field="frequency"><option value="monthly">Par mois</option><option value="once">Pour le projet</option></select></label></div>
  <p class="cost-context"></p>
  <div class="percent-fields" hidden><label>Taux sur le chiffre d’affaires<div class="input-wrap"><input data-field="rate" type="number" min="0" max="100" step="0.01" required inputmode="decimal"><span>% du CA</span></div></label><p>Appliqué au CA total du projet ou au service choisi ci-dessous, sur toute la période.</p></div>
  <details class="line-options"><summary>Rattachement et calcul <span class="assignment-label"></span></summary><div class="options-grid"><label>Catégorie<select data-field="category"></select></label><label>Mode de calcul<select data-field="calculation"><option value="amount">Quantité × montant</option><option value="percent">% du chiffre d’affaires</option></select></label><label class="service-assignment">Rattaché à<select data-field="serviceId"></select></label><label class="variable-option"><input data-field="variable" type="checkbox"><span>Varie avec l’activité dans les scénarios</span></label><p class="auto-variable" hidden>Ce pourcentage suit automatiquement le chiffre d’affaires.</p></div></details>
  <div class="line-footer"><span class="category-label"></span><strong class="line-total">—</strong></div>`;
  categoryOptions(fieldValue(card,'category'));serviceOptions(fieldValue(card,'serviceId'),line.serviceId);setValues(card,line);syncExpenseCard(card);card.querySelector('.remove-line').addEventListener('click',()=>removeLine('expense',line.id));return card;
}
function syncExpenseCard(card){const isPercent=fieldValue(card,'calculation').value==='percent';card.querySelector('.amount-fields').hidden=isPercent;card.querySelector('.percent-fields').hidden=!isPercent;for(const field of ['quantity','price','frequency','variable'])fieldValue(card,field).disabled=isPercent;fieldValue(card,'rate').disabled=!isPercent;card.querySelector('.variable-option').hidden=isPercent;card.querySelector('.auto-variable').hidden=!isPercent;card.querySelector('.cost-context').hidden=isPercent;}
function renderEditors(){const incomes=$('revenueList'),costs=$('expenseList');incomes.replaceChildren(...project.revenues.map(revenueCard));costs.replaceChildren(...project.expenses.map(expenseCard));
  if(!project.revenues.length){const p=document.createElement('p');p.className='empty-lines';p.textContent='Ajoutez un premier service ou produit pour construire vos revenus.';incomes.append(p);}if(!project.expenses.length){const p=document.createElement('p');p.className='empty-lines';p.textContent='Ajoutez vos frais à l’aide des catégories ci-dessus.';costs.append(p);}
}
const planner=initPlanner({getProject:()=>project,beforeChange:()=>isReady(),onChange:read=>{if(read&&!takeInput())return;render();saveDraft();},onRemove:id=>removeLine('consultant',id),toast,switchTab});
function populate(){ $('startDate').value=project.startDate;planner.populate(project); $('projectName').value=project.name;$('months').value=project.months;$('investment').value=project.investment;renderEditors();$('formError').hidden=true;setStale(false);render();saveDraft();}
function setStale(stale){$('resultsColumn').classList.toggle('stale',stale);document.querySelector('.contributions-panel').classList.toggle('stale',stale);}
function readCard(card){const result={id:card.dataset.id};card.querySelectorAll('[data-field]').forEach(input=>{const key=input.dataset.field;result[key]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;});result.name=result.name.trim()||(card.dataset.type==='revenue'?'Revenu sans nom':CATEGORIES[result.category]);if(card.dataset.type==='expense'){if(result.calculation==='percent'){result.quantity=1;result.price=0;result.frequency='once';}else result.rate=0;}return result;}
function readProjectFields(){return {version:3,name:$('projectName').value.trim().slice(0,80)||'Projet sans nom',startDate:$('startDate').value,...planner.readFields(),months:Number($('months').value),investment:Number($('investment').value),revenues:[...$('revenueList').querySelectorAll('.editor-card')].map(readCard),expenses:[...$('expenseList').querySelectorAll('.editor-card')].map(readCard)};}
function takeInput(){const invalid=[...$('assumptionForm').querySelectorAll('input:not(:disabled)')].find(input=>!input.validity.valid || (input.type==='number' && input.value===''));
  if(invalid){invalid.setAttribute('aria-invalid','true');$('formError').textContent=invalid.id==='startDate'?'Indiquez une date de début de projet valide.':invalid.type==='date'?'Renseignez les dates de début et de fin de chaque consultant.':invalid.id==='months'?'La durée doit être un nombre entier entre 1 et 60 mois.':'Complétez les montants et quantités avec des nombres positifs ou nuls, et les taux entre 0 et 100 %.';$('formError').hidden=false;setStale(true);return false;}
  $('assumptionForm').querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));
  const next=readProjectFields();
  if(!validProject(next)){const bad=next.consultants.find(c=>consultantProblems(c,next).length);if(bad){const card=[...$('consultantList').querySelectorAll('.consultant-card')].find(c=>c.dataset.id===bad.id);card?.querySelector('[data-cfield="endDate"]')?.setAttribute('aria-invalid','true');}$('formError').textContent=next.consultants.flatMap(c=>consultantProblems(c,next))[0]||'Vérifiez les lignes du budget et la date de début du projet.';$('formError').hidden=false;setStale(true);return false;}
  project=next;$('formError').hidden=true;setStale(false);return true;
}
function isReady(){if(takeInput())return true;const invalid=$('assumptionForm').querySelector('[aria-invalid]');if(invalid){const panel=invalid.closest('[role="tabpanel"]');if(panel)switchTab(panel.id==='consultantsPanel'?'consultants':panel.id==='revenuesPanel'?'revenues':'expenses');invalid.focus();}toast('Corrigez les champs signalés avant de continuer.');return false;}
function removeLine(type,id){
  const card=[...document.querySelectorAll('.editor-card')].find(e=>e.dataset.id===id);
  const invalidElsewhere=[...$('assumptionForm').querySelectorAll('input:not(:disabled)')].some(input=>!card?.contains(input)&&(!input.validity.valid||(input.type==='number'&&input.value==='')));
  if(invalidElsewhere){isReady();return;}
  const previous=calculate(project),next=readProjectFields();
  if(type==='revenue')next.revenues=next.revenues.filter(r=>r.id!==id);
  if(type==='consultant')next.consultants=next.consultants.filter(c=>c.id!==id);
  if(type==='expense')next.expenses=next.expenses.filter(e=>e.id!==id);
  else next.expenses=next.expenses.map(e=>{
    if(e.serviceId!==id)return e;
    if(e.calculation==='percent')return {...e,serviceId:'',calculation:'amount',quantity:1,price:previous.ordinaryExpenses.find(x=>x.id===e.id)?.total||0,frequency:'once',variable:true,rate:0};
    return {...e,serviceId:''};
  });
  if(!validProject(next)){isReady();return;}
  project=next;renderEditors();planner.populate(project);render();saveDraft();
  toast(type==='revenue'||type==='consultant'?'Ligne supprimée. Les coûts rattachés deviennent communs ; les taxes rattachées sont conservées en montant.':'Dépense supprimée.');
}
function updateLineMetadata(r){for(const type of ['revenue','expense']){const lines=type==='revenue'?r.revenues:r.expenses;const cards=$(type==='revenue'?'revenueList':'expenseList').querySelectorAll('.editor-card');cards.forEach(card=>{const line=lines.find(l=>l.id===card.dataset.id);if(!line)return;card.querySelector('.line-total').textContent=money(line.total);card.setAttribute('aria-label',line.name);card.querySelector('.remove-line').setAttribute('aria-label',`Supprimer ${line.name}`);if(type==='expense'){card.querySelector('.category-label').textContent=CATEGORIES[line.category];const hints={flights:'Quantité = billets ; coût unitaire = prix par billet.',lodging:'Quantité = nuitées ; coût unitaire = prix par nuit.',salaries:'Quantité = nombre de salariés ; coût unitaire = salaire et charges employeur.',contractors:'Quantité = prestations, journées ou forfaits ; indiquez le coût correspondant.',taxes:'Saisissez un montant, ou choisissez un pourcentage du CA dans les options.'};const hint=card.querySelector('.cost-context');hint.textContent=hints[line.category]||'';hint.hidden=line.calculation==='percent'||!hints[line.category];const current=fieldValue(card,'serviceId');serviceOptions(current,line.serviceId);card.querySelector('.assignment-label').textContent=line.serviceId?'Service rattaché':'Coût commun';}});}
  document.querySelectorAll('.months-label').forEach(e=>e.textContent=project.months);$('revenueCount').textContent=project.revenues.length;$('expenseCount').textContent=project.expenses.length;$('revenueSubtotal').textContent=money(r.ordinaryRevenues.reduce((s,l)=>s+l.total,0));$('expenseSubtotal').textContent=money(r.ordinaryExpenses.reduce((s,l)=>s+l.total,0));
}
function render(){const r=calculate(project);planner.render(r);$('periodLabel').textContent=`${project.months} mois`;$('totalResult').textContent=signed(r.total);$('resultHero').classList.toggle('negative',r.total<0);$('statusPill').textContent=r.total>0?'Projet rentable':r.total===0?'À l’équilibre':'Projet déficitaire';$('monthlyProfit').textContent=signed(r.monthly);$('thresholdValue').textContent=r.threshold===null?'Non calculable':money(r.threshold);$('revenueValue').textContent=money(r.revenue);$('costValue').textContent=money(r.totalCosts);$('marginValue').textContent=r.margin===null?'Non définie':`${percent(r.margin)} %`;$('savedCount').textContent=projects.length;
  $('thresholdText').textContent=r.threshold===null?(r.revenue===0?'Ajoutez des revenus pour estimer le CA minimum à atteindre.':'Les dépenses variables absorbent tout le CA : augmenter le volume dans les mêmes proportions ne suffit pas à dégager un bénéfice.'):'CA minimum estimé pour couvrir tous les coûts, avec la même répartition des services et les mêmes taux de coûts variables.';
  updateLineMetadata(r);renderBreakdown(r);renderScenarios();renderContributions(r);
}
function renderBreakdown(r){const list=$('costBreakdown');list.replaceChildren();const colors={flights:'#719886',lodging:'#a2b880',taxes:'#cfb476',contractors:'#8fa2b5',salaries:'#4f7663',other:'#b1b3a0',investment:'#c6c9bc'};const maximum=Math.max(...r.categories.map(c=>c.total),1);const visible=r.categories.filter(c=>c.total>0);for(const category of visible){const row=document.createElement('div');row.className='cost-category';const name=document.createElement('span');name.textContent=category.name;const value=document.createElement('strong');value.textContent=money(category.total);const track=document.createElement('div');track.className='cost-track';const bar=document.createElement('div');bar.style.width=`${category.total/maximum*100}%`;bar.style.background=colors[category.id];track.append(bar);row.append(name,value,track);list.append(row);}if(!visible.length){const p=document.createElement('p');p.className='empty-lines';p.textContent='La répartition apparaîtra avec vos premières dépenses.';list.append(p);}}
function renderScenarios(){const list=$('scenarios');list.replaceChildren();for(const [label,factor,change]of [['Prudent',.8,'−20 %'],['Central',1,'Prévu'],['Optimiste',1.2,'+20 %']]){const r=calculate(project,factor);const el=document.createElement('div');el.className='scenario'+(factor===1?' central':'');const top=document.createElement('div');top.className='scenario-top';top.append(document.createTextNode(label));const badge=document.createElement('span');badge.textContent=change;top.append(badge);const value=document.createElement('strong');value.textContent=signed(r.total);value.classList.toggle('loss',r.total<0);const detail=document.createElement('span');detail.textContent=`CA : ${money(r.revenue)}`;el.append(top,value,detail);list.append(el);}}
function renderContributions(r){$('contributionMonths').textContent=project.months;const body=$('contributions');body.replaceChildren();for(const line of r.services){const tr=document.createElement('tr');for(const [index,value]of [line.name,money(line.total),money(line.directCosts),signed(line.contribution)].entries()){const cell=document.createElement(index===0?'th':'td');if(index===0)cell.scope='row';cell.textContent=value;if(index===3)cell.className=line.contribution<0?'loss':'positive';tr.append(cell);}body.append(tr);}if(!r.services.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.className='empty-lines';td.textContent='Ajoutez un service ou un produit pour voir sa contribution.';tr.append(td);body.append(tr);}$('commonCostValue').textContent=money(r.commonCosts);}
$('assumptionForm').addEventListener('submit',e=>e.preventDefault());
$('assumptionForm').addEventListener('input',e=>{planner.onFormInput(e);if(e.target.dataset.field==='calculation')syncExpenseCard(e.target.closest('.editor-card'));if(takeInput()){render();saveDraft();}});
$('projectName').addEventListener('input',()=>{project.name=$('projectName').value.trim().slice(0,80)||'Projet sans nom';saveDraft();});
for(const tab of ['consultants','revenues','expenses']){$(tab+'Tab').addEventListener('click',()=>switchTab(tab));$(tab+'Tab').addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=['consultants','revenues','expenses'],idx=tabs.indexOf(tab);switchTab(e.key==='Home'?tabs[0]:e.key==='End'?tabs[2]:tabs[(idx+(e.key==='ArrowRight'?1:2))%3],true);}});}
$('addRevenueBtn').addEventListener('click',()=>{if(!isReady())return;if(project.revenues.length>=100){toast('Un projet peut contenir 100 lignes de revenus.');return;}project.revenues.push({id:uid(),name:'Nouveau service',kind:'service',quantity:1,price:0,frequency:'monthly'});renderEditors();render();saveDraft();const last=$('revenueList').lastElementChild;fieldValue(last,'name').focus();fieldValue(last,'name').select();});
for(const btn of document.querySelectorAll('[data-category]'))btn.addEventListener('click',()=>{if(!isReady())return;if(project.expenses.length>=100){toast('Un projet peut contenir 100 lignes de dépenses.');return;}project.expenses.push(expense(btn.dataset.category));renderEditors();render();saveDraft();const last=$('expenseList').lastElementChild;fieldValue(last,'name').focus();fieldValue(last,'name').select();});
$('saveBtn').addEventListener('click',()=>{if(!isReady())return;const existing=projects.find(item=>item.id===activeId);const record={id:activeId||uid(),data:structuredClone(project),updated:new Date().toISOString()};const next=existing?projects.map(p=>p.id===activeId?record:p):[record,...projects];if(writeStorage(KEYS.projects,next)){projects=next;activeId=record.id;saveDraft();$('savedCount').textContent=projects.length;toast(existing?'Projet mis à jour.':'Projet enregistré dans Mes projets.');}else{toast('Enregistrement impossible. Exportez la simulation pour la conserver.');}});
function showProjects(){const list=$('projectList');list.replaceChildren();if(!projects.length){const p=document.createElement('p');p.className='empty-projects';p.textContent='Enregistrez votre premier budget pour le retrouver ici.';list.append(p);}for(const item of projects){const r=calculate(item.data),row=document.createElement('div');row.className='saved-project';const info=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('p');title.textContent=item.data.name;meta.textContent=`${item.data.consultants.length} consultants · ${item.data.revenues.length} autres revenus · ${item.data.expenses.length} dépenses · ${item.data.months} mois · ${signed(r.total)}`;info.append(title,meta);const actions=document.createElement('div');actions.className='saved-actions';const open=document.createElement('button');open.className='button secondary';open.textContent='Ouvrir';open.addEventListener('click',()=>{project=structuredClone(item.data);activeId=item.id;populate();$('projectsDialog').close();toast('Projet chargé.');});const remove=document.createElement('button');remove.className='delete-project';remove.textContent='Supprimer';remove.setAttribute('aria-label',`Supprimer ${item.data.name}`);remove.addEventListener('click',()=>{const next=projects.filter(p=>p.id!==item.id);if(!writeStorage(KEYS.projects,next)){toast('Suppression impossible : stockage indisponible.');return;}projects=next;if(activeId===item.id)activeId=null;saveDraft();$('savedCount').textContent=projects.length;showProjects();toast('Projet supprimé. Le brouillon reste disponible.');});actions.append(open,remove);row.append(info,actions);list.append(row);}}
$('projectsBtn').addEventListener('click',()=>{showProjects();$('projectsDialog').showModal();});
$('methodBtn').addEventListener('click',()=>$('methodDialog').showModal());
$('newBtn').addEventListener('click',()=>$('confirmDialog').showModal());
$('confirmNewBtn').addEventListener('click',()=>{activeId=null;project=blankProject();populate();switchTab('consultants');$('confirmDialog').close();$('projectName').focus();$('projectName').select();toast('Nouveau projet : ajoutez vos consultants, leurs dates et leurs coûts.');});
document.querySelectorAll('.close-dialog').forEach(btn=>btn.addEventListener('click',()=>btn.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close();}}));
